configuration.jsScript:
// 解析 UAV Defender MQTT v2 封装：按主题/包装键识别分类，取出 body 落到遥测或设备属性
function toObj(v) {
  if (v == null) { return null; }
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  return typeof v === 'object' ? v : null;
}
var KINDS = {
  dr200Availability: 'availability',
  dr200Realtime: 'realtime',
  dr200Heartbeat: 'heartbeat',
  dr200Inbound: 'inbound',
  dr200StrikeReport: 'strikeReport',
  dr200Modules: 'modules',
  dr200ModuleLocations: 'moduleLocations',
  dr200SystemInfo: 'systemInfo',
  dr200Whitelist: 'whitelist',
  dr200DefenseAreas: 'defenseAreas',
  dr200Spectrum: 'spectrum',
  dr200CommandResponse: 'commandResponse'
};
var kind = null;
var env = null;
for (var k in KINDS) {
  if (msg[k] != null) { kind = KINDS[k]; env = toObj(msg[k]); break; }
}
if (kind == null) {
  var tp = String(metadata.mqttTopic == null ? '' : metadata.mqttTopic).split('/');
  var c = tp.length > 5 ? tp[4] : '';
  var n = tp.length > 5 ? tp[5] : '';
  if (c === 'availability') {
    kind = 'availability';
  } else if (c === 'telemetry') {
    if (n === 'heartbeat') { kind = 'heartbeat'; } else if (n === 'realtime') { kind = 'realtime'; }
  } else if (c === 'events') {
    if (n === 'inbound') { kind = 'inbound'; } else if (n === 'strike-report') { kind = 'strikeReport'; }
  } else if (c === 'state') {
    if (n === 'modules') { kind = 'modules'; }
    else if (n === 'module-locations') { kind = 'moduleLocations'; }
    else if (n === 'system-info') { kind = 'systemInfo'; }
    else if (n === 'whitelist') { kind = 'whitelist'; }
    else if (n === 'defense-areas') { kind = 'defenseAreas'; }
  } else if (c === 'streams' && n === 'module-spectrum') {
    kind = 'spectrum';
  } else if (c === 'responses') {
    kind = 'commandResponse';
  }
}
if (kind == null) {
  return {msg: msg, metadata: metadata, msgType: msgType};
}
if (env == null) { env = msg; }
var body = toObj(env.body);
if (body == null) { body = env; }

function isArr(v) { return v != null && Array.isArray(v); }
var out = {};
var attrs = false;
if (env.ts != null) { out.deviceTs = Number(env.ts); }

if (kind === 'availability') {
  attrs = true;
  if (env.sn != null) { out.sn = String(env.sn); }
  if (body.status != null) {
    out.deviceStatus = String(body.status);
    out.online = body.status === 'online' ? 1 : 0;
  }
  if (body.reason != null) { out.statusReason = String(body.reason); }
  if (body.software_version != null) { out.softwareVersion = String(body.software_version); }
} else if (kind === 'heartbeat') {
  if (body.status != null) { out.heartbeatStatus = String(body.status); }
  if (body.uptime_seconds != null) { out.uptimeSeconds = Number(body.uptime_seconds); }
} else if (kind === 'realtime') {
  if (isArr(body.alerts)) { out.alerts = JSON.stringify(body.alerts); out.alertCount = body.alerts.length; }
  if (isArr(body.palerts)) { out.palerts = JSON.stringify(body.palerts); out.palertCount = body.palerts.length; }
  if (isArr(body.fpvs)) { out.fpvs = JSON.stringify(body.fpvs); out.fpvCount = body.fpvs.length; }
} else if (kind === 'inbound') {
  if (isArr(body.drone_targets)) {
    out.droneTargets = JSON.stringify(body.drone_targets);
    out.targetCount = body.drone_targets.length;
    var t = body.drone_targets.length ? body.drone_targets[body.drone_targets.length - 1] : null;
    if (t != null) {
      if (t.target_id != null) { out.targetId = String(t.target_id); }
      if (t.model != null) { out.targetModel = String(t.model); }
      if (t.rssi != null) { out.targetRssi = t.rssi; }
      if (t.freq_point != null) { out.targetFreq = t.freq_point; }
      if (t.location_lng != null) { out.targetLng = t.location_lng; }
      if (t.location_lat != null) { out.targetLat = t.location_lat; }
      if (t.remote_control_lon != null) { out.rcLng = t.remote_control_lon; }
      if (t.remote_control_lat != null) { out.rcLat = t.remote_control_lat; }
      if (t.drone_type != null) { out.targetDroneType = t.drone_type; }
      if (t.module_id != null) { out.sourceModuleId = String(t.module_id); }
    }
  }
} else if (kind === 'strikeReport') {
  if (body.source_report_id != null) { out.sourceReportId = String(body.source_report_id); }
  if (body.strike_mode != null) { out.strikeMode = body.strike_mode; }
  if (isArr(body.frequency)) { out.strikeFrequency = body.frequency.join(','); }
  if (isArr(body.model)) { out.strikeModels = body.model.join(','); }
  if (isArr(body.target_id)) { out.strikeTargetIds = body.target_id.join(','); }
  if (body.directed_strike_detail != null) { out.directedStrikeDetail = JSON.stringify(body.directed_strike_detail); }
  if (body.start_time != null) { out.strikeStartTime = String(body.start_time); }
  if (body.end_time != null) { out.strikeEndTime = String(body.end_time); }
  if (body.duration != null) { out.strikeDuration = body.duration; }
  if (body.result != null) { out.strikeResult = body.result; }
  if (body.module_id != null) { out.strikeModuleId = String(body.module_id); }
} else if (kind === 'modules') {
  if (body.version != null) { out.modulesVersion = body.version; }
  if (isArr(body.modules)) { out.moduleCount = body.modules.length; out.modules = JSON.stringify(body.modules); }
  else if (body.count != null) { out.moduleCount = body.count; }
} else if (kind === 'moduleLocations') {
  if (body.version != null) { out.locationsVersion = body.version; }
  if (isArr(body.locations)) { out.locationCount = body.locations.length; out.moduleLocations = JSON.stringify(body.locations); }
  else if (body.count != null) { out.locationCount = body.count; }
} else if (kind === 'systemInfo') {
  if (body.version != null) { out.systemInfoVersion = body.version; }
  if (body.system_info != null) { out.systemInfo = JSON.stringify(body.system_info); }
} else if (kind === 'whitelist') {
  if (body.version != null) { out.whitelistVersion = body.version; }
  if (isArr(body.entries)) { out.whitelistCount = body.entries.length; out.whitelist = JSON.stringify(body.entries); }
  else if (body.count != null) { out.whitelistCount = body.count; }
  if (body.hash != null) { out.whitelistHash = String(body.hash); }
} else if (kind === 'defenseAreas') {
  if (body.version != null) { out.defenseAreaVersion = body.version; }
  if (isArr(body.areas)) { out.defenseAreaCount = body.areas.length; out.defenseAreas = JSON.stringify(body.areas); }
  else if (body.count != null) { out.defenseAreaCount = body.count; }
} else if (kind === 'spectrum') {
  if (body.module_id != null) { out.spectrumModuleId = String(body.module_id); }
  if (body.min_freq != null) { out.spectrumMinFreq = body.min_freq; }
  if (body.max_freq != null) { out.spectrumMaxFreq = body.max_freq; }
  if (isArr(body.values)) { out.spectrumPointCount = body.values.length; out.spectrumValues = JSON.stringify(body.values); }
} else if (kind === 'commandResponse') {
  if (env.operation_id != null) { out.operationId = String(env.operation_id); }
  if (body.success != null) { out.commandSuccess = body.success ? 1 : 0; }
  if (body.code != null) { out.commandCode = String(body.code); }
  if (body.status_code != null) { out.commandStatusCode = body.status_code; }
  if (body.message != null) { out.commandMessage = String(body.message); }
  if (body.data != null) { out.commandData = JSON.stringify(body.data); }
}
return {msg: out, metadata: metadata, msgType: attrs ? 'POST_ATTRIBUTES_REQUEST' : 'POST_TELEMETRY_REQUEST'};
